update pubcar_car_attr t set t.b_id = #{newAttrBId}

    , t.register_date= #{registerDate}


    , t.engine_num= #{engineNum}


    , t.frame_num= #{frameNum}


    , t.accident_situation= #{accidentSituation}


    , t.group_id= #{groupId}



        t.attr_id= #{attrId}


        and t.b_id= #{bId}
